c047.try_sql:
-- Left to right: (1 UNION ALL 1) MINUS 2 gives one row. With parentheses: two
SELECT 1 AS x FROM dual UNION ALL SELECT 1 FROM dual MINUS SELECT 2 FROM dual;
SELECT 1 AS x FROM dual UNION ALL (SELECT 1 FROM dual MINUS SELECT 2 FROM dual);

c406.try_sql:
-- Customers 1 (US) and 5 (NULL): INTERSECT gives US and NULL without repeats, IN gives US twice
SELECT country_code FROM customers
INTERSECT
SELECT country_code FROM customers WHERE customer_id IN (1, 5);
SELECT c.country_code FROM customers c
WHERE c.country_code IN (SELECT country_code FROM customers WHERE customer_id IN (1, 5));

c407.try_sql:
-- (1 UNION 2) INTERSECT 2 gives only 2. With parentheses around INTERSECT: 1 and 2
SELECT 1 AS x FROM dual UNION SELECT 2 FROM dual INTERSECT SELECT 2 FROM dual;
SELECT 1 AS x FROM dual UNION (SELECT 2 FROM dual INTERSECT SELECT 2 FROM dual);

c408.try_sql:
-- The direction matters: departments MINUS employees gives 40, the reverse gives NULL (Grant)
SELECT department_id FROM departments MINUS SELECT department_id FROM employees;
SELECT department_id FROM employees MINUS SELECT department_id FROM departments;

c411.try_sql:
-- First: different numbers of columns (01789). Second: DATE and text (01790)
SELECT employee_id, last_name FROM employees UNION SELECT department_id FROM departments;
SELECT hire_date FROM employees UNION SELECT last_name FROM employees;

c1451.try_sql:
-- INTERSECT returns US and NULL, IN only US (NULL = NULL is UNKNOWN)
SELECT country_code FROM customers
INTERSECT
SELECT country_code FROM customers WHERE customer_id IN (3, 5);
SELECT DISTINCT c.country_code FROM customers c
WHERE c.country_code IN (SELECT country_code FROM customers WHERE customer_id IN (3, 5));

c1452.try_sql:
-- Order 1006 has the time 23:30: without TRUNC there is no row, with TRUNC there is
SELECT order_date FROM orders INTERSECT SELECT DATE '2024-03-31' FROM dual;
SELECT TRUNC(order_date) FROM orders INTERSECT SELECT DATE '2024-03-31' FROM dual;

c1456.try_sql:
-- B has a NULL (Grant). MINUS: department 40 remains. NOT IN: nothing
SELECT department_id FROM departments MINUS SELECT department_id FROM employees;
SELECT department_id FROM departments
WHERE department_id NOT IN (SELECT department_id FROM employees);

c1457.try_sql:
-- With NULL the query runs but subtracts nothing (5 customers). MINUS on the key: only Umbrella
SELECT customer_id, customer_name FROM customers
MINUS SELECT customer_id, NULL FROM orders;
SELECT customer_id, customer_name FROM customers
WHERE customer_id IN (SELECT customer_id FROM customers MINUS SELECT customer_id FROM orders);

c1458.try_sql:
-- A final UNION removes duplicates from the whole: 1, 2. A final UNION ALL keeps the repeat: 1, 1
SELECT 1 AS x FROM dual UNION ALL SELECT 1 FROM dual UNION SELECT 2 FROM dual;
SELECT 1 AS x FROM dual UNION SELECT 1 FROM dual UNION ALL SELECT 1 FROM dual;

c1459.try_sql:
-- NUMBER with NULL works; DATE with a string literal raises ORA-01790
SELECT salary FROM employees UNION SELECT NULL FROM dual;
SELECT hire_date FROM employees UNION SELECT '2024-01-01' FROM dual;

c1460.try_sql:
-- An expression in a compound query's ORDER BY: error. An inline view: works
SELECT last_name AS name FROM employees UNION SELECT customer_name FROM customers ORDER BY UPPER(name);
SELECT name FROM (SELECT last_name AS name FROM employees UNION SELECT customer_name FROM customers)
ORDER BY UPPER(name);
